using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using BepInEx.Logging;
using HarmonyLib;
using SleepyNodes;

namespace IronNestModTemplate;

/// <summary>
/// Applies missions/extreme-counter-battery.json to a freshly loaded mission graph.
///
/// The rule file is generated by scripts/build_mission_rules.py from the plugin's
/// own mission dumps. Edit the JSON to change teleprinter text, timer seconds or
/// spawn counts without touching C# or re-doing the reverse engineering.
///
/// Scope (by design): only scalar field values on existing nodes. Graph rewiring,
/// node insertion and entity visual/role changes stay in the build plugin.
/// </summary>
[HarmonyPatch(typeof(MissionGraph), "OnMissionLoaded")]
internal static class Patch_MissionGraphBuild
{
    private const string RuleFileName = "extreme-counter-battery.json";

    private sealed class RuleSet
    {
        public string mission { get; set; } = "";
        public string base_graph { get; set; } = "";
        public List<Rule> rules { get; set; } = new();
    }

    private sealed class Rule
    {
        public int index { get; set; }
        public string type { get; set; } = "";
        public Dictionary<string, JsonElement> set { get; set; } = new();
    }

    private static string ResolveRulePath()
    {
        // Search next to the plugins dir first (shipping layout), then the
        // game root and the current directory (development layout).
        // BepInEx 6 has no Paths class; walk up from BepInEx/plugins.
        string pluginsDir = AppDomain.CurrentDomain.BaseDirectory;
        string root = Directory.GetParent(pluginsDir)?.Parent?.FullName ?? pluginsDir;
        string[] candidates =
        {
            Path.Combine(root, "BepInEx", "plugins", "missions", RuleFileName),
            Path.Combine(root, "BepInEx", "config", "missions", RuleFileName),
            Path.Combine(root, "missions", RuleFileName),
            Path.Combine(Directory.GetCurrentDirectory(), "missions", RuleFileName),
        };
        return candidates.FirstOrDefault(File.Exists) ?? candidates[0];
    }

    private static void Postfix(MissionGraph __instance)
    {
        string path = ResolveRulePath();
        if (!File.Exists(path))
        {
            Core.Logger?.LogWarning($"[mission] rule file not found: {path}");
            return;
        }

        RuleSet rules;
        try
        {
            rules = JsonSerializer.Deserialize<RuleSet>(File.ReadAllText(path));
        }
        catch (Exception ex)
        {
            Core.Logger?.LogError($"[mission] cannot parse {path}: {ex.Message}");
            return;
        }
        if (rules == null || rules.rules == null || rules.rules.Count == 0)
        {
            Core.Logger?.LogWarning("[mission] rule file has no rules");
            return;
        }

        // Only apply to the mission the rules were generated from. ML mission
        // IDs may include a space ("Artillery Introduction"), so compare both
        // the raw ID and an all-lowercase alphanumeric form.
        string graphId = __instance.MissionID ?? "";
        string normalized = Normalize(graphId);
        bool match = string.Equals(graphId, rules.base_graph, StringComparison.OrdinalIgnoreCase)
                     || string.Equals(normalized, Normalize(rules.base_graph), StringComparison.OrdinalIgnoreCase)
                     || string.Equals(normalized, Normalize(rules.mission), StringComparison.OrdinalIgnoreCase);
        if (!match)
        {
            Core.Logger?.LogDebug($"[mission] skip graph '{graphId}' (rules for '{rules.base_graph}')");
            return;
        }

        var nodes = __instance.nodes;
        if (nodes == null)
        {
            Core.Logger?.LogWarning("[mission] graph has no nodes list");
            return;
        }

        int applied = 0;
        foreach (Rule rule in rules.rules)
        {
            if (rule.index < 0 || rule.index >= nodes.Count)
            {
                Core.Logger?.LogWarning($"[mission] index {rule.index} out of range (nodes={nodes.Count})");
                continue;
            }

            Node node = nodes[rule.index];
            string actualType = node.GetType().Name;
            if (!string.Equals(actualType, rule.type, StringComparison.Ordinal))
            {
                Core.Logger?.LogWarning(
                    $"[mission] index {rule.index} expected {rule.type}, got {actualType}; skipped");
                continue;
            }

            foreach (KeyValuePair<string, JsonElement> entry in rule.set)
            {
                string fieldPath = entry.Key;
                try
                {
                    string before = ReadField(node, fieldPath);
                    WriteField(node, fieldPath, entry.Value);
                    string after = ReadField(node, fieldPath);
                    Core.Logger?.LogInfo($"[mission] [{rule.index}] {fieldPath}: {before} -> {after}");
                    applied++;
                }
                catch (Exception ex)
                {
                    Core.Logger?.LogError(
                        $"[mission] [{rule.index}] cannot set {fieldPath}: {ex.Message}");
                }
            }
        }

        Core.Logger?.LogInfo($"[mission] applied {applied} field changes to '{graphId}' from {path}");
    }

    private static string Normalize(string value)
    {
        return new string((value ?? "")
            .Where(char.IsLetterOrDigit)
            .Select(char.ToLowerInvariant)
            .ToArray());
    }

    private static object ResolveTarget(Node node, string fieldPath, out FieldInfo field)
    {
        string[] parts = fieldPath.Split('.');
        object target = node;
        Type type = node.GetType();
        for (int i = 0; i < parts.Length - 1; i++)
        {
            FieldInfo parent = type.GetField(parts[i], BindingFlags.Public | BindingFlags.Instance)
                               ?? throw new MissingFieldException(type.FullName, parts[i]);
            object value = parent.GetValue(target);
            if (value == null)
                throw new InvalidOperationException($"field {parts[i]} is null; cannot reach {fieldPath}");
            target = value;
            type = value.GetType();
        }
        field = type.GetField(parts[^1], BindingFlags.Public | BindingFlags.Instance)
                ?? throw new MissingFieldException(type.FullName, parts[^1]);
        return target;
    }

    private static string ReadField(Node node, string fieldPath)
    {
        object target = ResolveTarget(node, fieldPath, out FieldInfo field);
        object value = field.GetValue(target);
        if (value == null) return "<null>";
        string text = value.ToString() ?? "";
        // Teleprinter text can be multi-line; keep logs scannable.
        return text.Length > 80 ? text.Substring(0, 80).Replace("\n", "\\n") + "..." : text.Replace("\n", "\\n");
    }

    private static void WriteField(Node node, string fieldPath, JsonElement value)
    {
        object target = ResolveTarget(node, fieldPath, out FieldInfo field);
        Type fieldType = field.FieldType;
        object converted;

        if (fieldType == typeof(string))
        {
            converted = value.GetString() ?? "";
            // TextIdentifier has both Key and Raw. Get() prefers whichever the
            // game filled; the plugin's dump prints inline rich text as 'key',
            // so mirror the value into both to make the patch effective either
            // way. This is safe for localization keys too (Raw becomes the key
            // string, which Get() can still resolve).
            if (field.Name == "Key" && target.GetType().Name == "TextIdentifier")
            {
                FieldInfo raw = target.GetType().GetField("Raw", BindingFlags.Public | BindingFlags.Instance);
                if (raw != null) raw.SetValue(target, converted);
            }
        }
        else if (fieldType == typeof(int))
        {
            converted = value.ValueKind == JsonValueKind.String
                ? int.Parse(value.GetString()!, CultureInfo.InvariantCulture)
                : value.GetInt32();
        }
        else if (fieldType == typeof(float))
        {
            converted = value.ValueKind == JsonValueKind.String
                ? float.Parse(value.GetString()!, CultureInfo.InvariantCulture)
                : (float)value.GetDouble();
        }
        else if (fieldType.IsEnum)
        {
            string name = value.GetString() ?? "";
            if (!Enum.IsDefined(fieldType, name))
                throw new ArgumentException($"{name} is not a value of {fieldType.Name}");
            converted = Enum.Parse(fieldType, name);
        }
        else
        {
            throw new NotSupportedException($"field type {fieldType.FullName} is not patchable");
        }

        field.SetValue(target, converted);
    }
}
